import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ai-writing-tools`,heroTitle:`Build your best AI writing toolkit in minutes`,heroSubtitle:`Perplexity Computer analyzes your content, learns your voice, and builds a custom writing AI suite for blogs, books, and scripts — automatically.`,inputUrlCta:`Analyze`,inputUrlPlaceholder:`Blog, site, social media`,inputUrlPrefill:`Go to {url} and perform a deep analysis of the writing style, tone, voice, audience, content formats, and subject matter. Extract the brand voice guidelines, sentence structure patterns, vocabulary level, and messaging pillars. Then build me a comprehensive AI writing tools suite as a custom web app deployed to a live URL. The app should include: 1) A blog post generator that produces on-brand long-form articles with SEO-optimized headlines, subheadings, meta descriptions, and internal linking suggestions — matching my voice and tone exactly, 2) A book chapter drafting tool where I can input an outline or chapter brief and get polished prose in my writing style — suitable for creative writing, nonfiction, or memoir, 3) A YouTube script writer that generates hook-driven scripts with timestamps, B-roll cues, and CTA placements optimized for watch time, 4) A social media and short-form copy generator for LinkedIn posts, Twitter threads, and email newsletters — all on-brand, 5) A style guide panel that displays my extracted voice, tone, and writing rules so I can review and tweak them, 6) A content repurposer that takes any piece of content and reformats it across blog, script, social, and email formats while preserving voice consistency. Save my writing profile so future sessions start with my guidelines already loaded. Include a quality scoring system that rates each output on readability, engagement potential, and brand voice alignment.`,heroOverlaySteps:[`Analyzing your content for voice, tone, and writing style`,`Building AI writing tools tailored to your brand voice`,`Configuring generators for blogs, books, scripts, and social copy`,`Your custom writing suite deployed — ready to create`],generatingSteps:[`Visiting {url} to extract writing style, voice, tone, and content patterns`,`Designing an agent to generate on-brand content across blogs, books, and scripts`,`Configuring format-specific generators for long-form, video scripts, and social copy`,`Setting up your custom AI writing toolkit with style guide and quality scoring`],featureSectionTitle:`From your voice to unlimited content`,featureCardTitles:[`Connects to your writing stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Notion, Google Drive, Slack, Google Sheets — Computer sends drafts, outlines, and scripts straight into the tools you already write in.`,`SEO-optimized blog posts. Book chapters in your voice. YouTube scripts with hooks and timestamps. Social copy and email newsletters. Content repurposed across every format.`],capabilitySectionTitle:`Your writing team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, get back a full AI writing suite tuned to your voice.`,capabilityCards:[{title:`Voice Extraction`,description:`Computer can study your existing content — tone, vocabulary, sentence structure, audience — and build a precise writing profile that keeps every output on-brand.`},{title:`Long-Form Drafting`,description:`Computer can generate full blog posts and book chapters from a brief or outline — complete with headlines, subheadings, and SEO structure matching your style.`},{title:`Script Generation`,description:`Computer can write YouTube scripts with hooks, timestamps, B-roll cues, and CTAs — optimized for watch time and tuned to your delivery style.`},{title:`Connect Your Tools`,description:`Computer can push drafts to Google Docs, organize assets in Notion, sync data in Google Sheets, and notify your team in Slack — all within one workflow.`},{title:`Learns Your Style`,description:`Computer can remember your voice guidelines, past drafts, and preferred edits — so every piece of content gets sharper and more on-brand over time.`},{title:`Quality Monitoring`,description:`Computer can score every output on readability, engagement potential, and voice alignment — and alert you when a draft needs human attention.`}]});export{t as default};
